/* ── OpenLearnHub Shared Styles ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy:     #0a0a23;
  --gold:     #feac32;
  --gold-dk:  #e09800;
  --blue:     #002ead;
  --bg:       #f6f7fb;
  --card-bg:  #ffffff;
  --text:     #1e293b;
  --muted:    #64748b;
  --border:   #e2e8f0;
  --radius:   10px;
  --header-h: 64px;
  --max-w:    1160px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  padding: .5rem 1rem;
  background: var(--gold);
  color: var(--navy);
  font-weight: 600;
  border-radius: 0 0 6px 0;
  z-index: 9999;
}
.skip-link:focus { left: 0; }

/* ── Screen reader only ── */
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ── Layout ── */
.container {
  width: 100%;
  max-width: var(--max-w);
  margin-inline: auto;
  padding-inline: 1.25rem;
}

/* ── Header ── */
.site-header {
  background: var(--navy);
  height: var(--header-h);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0,0,0,.25);
}
.header-inner {
  height: var(--header-h);
  display: flex;
  align-items: center;
  gap: 1rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.1rem;
  font-weight: 800;
  color: #fff;
  text-decoration: none;
  white-space: nowrap;
  flex-shrink: 0;
}
.logo-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px; height: 30px;
  background: var(--gold);
  color: var(--navy);
  border-radius: 4px;
  font-size: .9rem;
  font-weight: 900;
}

/* Search */
.search-wrap {
  flex: 1;
  max-width: 500px;
  position: relative;
  display: flex;
  align-items: center;
}
.search-icon {
  position: absolute;
  left: .75rem;
  color: #94a3b8;
  pointer-events: none;
  flex-shrink: 0;
}
.search-input {
  width: 100%;
  height: 38px;
  padding: 0 1rem 0 2.5rem;
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 20px;
  background: rgba(255,255,255,.08);
  color: #fff;
  font-size: .85rem;
  outline: none;
  transition: border-color .2s, background .2s;
}
.search-input::placeholder { color: rgba(255,255,255,.4); }
.search-input:focus { border-color: var(--gold); background: rgba(255,255,255,.12); }

/* Main nav */
.main-nav {
  display: flex;
  align-items: center;
  gap: .25rem;
  flex-shrink: 0;
}
.nav-link {
  padding: .45rem .8rem;
  color: rgba(255,255,255,.85);
  text-decoration: none;
  font-size: .875rem;
  font-weight: 500;
  border-radius: 6px;
  transition: color .15s, background .15s;
}
.nav-link:hover { color: #fff; background: rgba(255,255,255,.1); }
.nav-link:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.nav-donate {
  background: var(--gold);
  color: var(--navy) !important;
  font-weight: 700;
  padding: .45rem 1rem;
}
.nav-donate:hover { background: var(--gold-dk) !important; color: var(--navy) !important; }

/* Hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  padding: .4rem;
  border-radius: 6px;
  transition: background .15s;
  margin-left: auto;
  flex-shrink: 0;
}
.hamburger:hover { background: rgba(255,255,255,.1); }
.hamburger:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

/* Mobile menu */
.mobile-menu {
  display: none;
  flex-direction: column;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,.1);
  padding: .5rem 1.25rem 1rem;
  gap: .25rem;
}
.mobile-menu.is-open { display: flex; }
.mobile-nav-link {
  color: rgba(255,255,255,.85);
  text-decoration: none;
  font-size: 1rem;
  font-weight: 500;
  padding: .65rem .75rem;
  border-radius: 8px;
  transition: background .15s, color .15s;
}
.mobile-nav-link:hover { background: rgba(255,255,255,.1); color: #fff; }
.mobile-nav-link:focus-visible { outline: 2px solid var(--gold); }

@media (max-width: 768px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .search-wrap { max-width: none; }
}

/* ── Banner ── */
.banner {
  background: var(--navy);
  color: rgba(255,255,255,.9);
  text-align: center;
  padding: .6rem 1rem;
  font-size: .85rem;
  border-top: 1px solid rgba(255,255,255,.08);
}
.banner-link {
  color: var(--gold);
  text-decoration: none;
  font-weight: 600;
}
.banner-link:hover { text-decoration: underline; }
.banner-link:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

/* ── Tags ── */
.tag {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  padding: .22rem .55rem;
  border-radius: 4px;
  text-decoration: none;
  cursor: pointer;
  transition: opacity .15s;
}
.tag:hover { opacity: .85; }
.tag:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.tag-ai       { background: #dbeafe; color: #1d4ed8; }
.tag-scraping { background: #d1fae5; color: #065f46; }
.tag-db       { background: #ffedd5; color: #9a3412; }
.tag-es       { background: #ede9fe; color: #5b21b6; }
