  font-weight: 600;
  border-radius: 0 0 6px 0;
  z-index: 9999;
}
.skip-link:focus { left: 0; }

/* ── Screen reader only ── */
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ── Layout ── */
.container {
  width: 100%;
  max-width: var(--max-w);
  margin-inline: auto;
  padding-inline: 1.25rem;
}

/* ── Header ── */
.site-header {
  background: var(--navy);
  height: var(--header-h);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0,0,0,.25);
}
.header-inner {
  height: var(--header-h);
  display: flex;
  align-items: center;
  gap: 1rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.1rem;
  font-weight: 800;
  color: #fff;
  text-decoration: none;
  white-space: nowrap;
  flex-shrink: 0;
}
.logo-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px; height: 30px;
  background: var(--gold);
  color: var(--navy);
  border-radius: 4px;
  font-size: .9rem;
  font-weight: 900;
}

/* Search */
.search-wrap {
  flex: 1;
  max-width: 500px;
  position: relative;
  display: flex;
  align-items: center;
}
.search-icon {
  position: absolute;
  left: .75rem;
  color: #94a3b8;
  pointer-events: none;
  flex-shrink: 0;
}
.search-input {
  width: 100%;
  height: 38px;
  padding: 0 1rem 0 2.5rem;
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 20px;
  background: rgba(255,255,255,.08);
  color: #fff;
  font-size: .85rem;
  outline: none;
  transition: border-color .2s, background .2s;
}
.search-input::placeholder { color: rgba(255,255,255,.4); }
.search-input:focus { border-color: var(--gold); background: rgba(255,255,255,.12); }

/* Main nav */
.main-nav {
  display: flex;
  align-items: center;
  gap: .25rem;
  flex-shrink: 0;
}
.nav-link {
  padding: .45rem .8rem;
  color: rgba(255,255,255,.85);
  text-decoration: none;
  font-size: .875rem;
  font-weight: 500;
  border-radius: 6px;
  transition: color .15s, background .15s;
}
.nav-link:hover { color: #fff; background: rgba(255,255,255,.1); }
.nav-link:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.nav-donate {
  background: var(--gold);
  color: var(--navy) !important;
  font-weight: 700;
  padding: .45rem 1rem;
}
.nav-donate:hover { background: var(--gold-dk) !important; color: var(--navy) !important; }

/* Hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  padding: .4rem;
  border-radius: 6px;
  transition: background .15s;
  margin-left: auto;
  flex-shrink: 0;
}
.hamburger:hover { background: rgba(255,255,255,.1); }
.hamburger:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

/* Mobile menu */
.mobile-menu {
  display: none;
  flex-direction: column;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,.1);
  padding: .5rem 1.25rem 1rem;
  gap: .25rem;
}
.mobile-menu.is-open { display: flex; }
.mobile-nav-link {
  color: rgba(255,255,255,.85);
  text-decoration: none;
  font-size: 1rem;
  font-weight: 500;
  padding: .65rem .75rem;
  border-radius: 8px;
  transition: background .15s, color .15s;
}
.mobile-nav-link:hover { background: rgba(255,255,255,.1); color: #fff; }
.mobile-nav-link:focus-visible { outline: 2px solid var(--gold); }

@media (max-width: 768px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .search-wrap { max-width: none; }
}

/* ── Banner ── */
.banner {
  background: var(--navy);
  color: rgba(255,255,255,.9);
  text-align: center;
  padding: .6rem 1rem;
  font-size: .85rem;
  border-top: 1px solid rgba(255,255,255,.08);
}
.banner-link {
  color: var(--gold);
  text-decoration: none;
  font-weight: 600;
}
.banner-link:hover { text-decoration: underline; }
.banner-link:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

/* ── Tags ── */
.tag {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  padding: .22rem .55rem;
  border-radius: 4px;
  text-decoration: none;
  cursor: pointer;
  transition: opacity .15s;
}
.tag:hover { opacity: .85; }
.tag:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.tag-ai       { background: #dbeafe; color: #1d4ed8; }
.tag-scraping { background: #d1fae5; color: #065f46; }
.tag-db       { background: #ffedd5; color: #9a3412; }
.tag-es       { background: #ede9fe; color: #5b21b6; }
.tag-de       { background: #ccfbf1; color: #115e59; }
.tag-js       { background: #fef9c3; color: #854d0e; }
.tag-py       { background: #e0f2fe; color: #0c4a6e; }
.tag-react    { background: #f0fdf4; color: #15803d; }
.tag-css      { background: #fdf4ff; color: #7e22ce; }
.tag-node     { background: #f0fdf4; color: #166534; }
.tag-general  { background: #f1f5f9; color: #334155; }

/* ── Avatars ── */
.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--gold);
  color: var(--navy);
  font-weight: 700;
  border-radius: 50%;
  flex-shrink: 0;
  text-transform: uppercase;
}
.avatar-sm  { width: 32px; height: 32px; font-size: .85rem; }
.avatar-xs  { width: 24px; height: 24px; font-size: .7rem; }
.avatar-md  { width: 40px; height: 40px; font-size: 1rem; }

/* ── Footer ── */
.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,.75);
  margin-top: 3rem;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 2fr 1fr;
  gap: 2.5rem;
  padding: 3rem 1.25rem 2rem;
}
@media (max-width: 768px) { .footer-inner { grid-template-columns: 1fr; gap: 1.5rem; } }
.footer-logo { color: #fff; margin-bottom: .75rem; display: flex; }
.footer-tagline { font-size: .85rem; line-height: 1.7; color: rgba(255,255,255,.55); }
.footer-heading { font-size: .75rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: rgba(255,255,255,.5); margin-bottom: .75rem; }
.footer-tags { display: flex; flex-wrap: wrap; gap: .4rem; }
.footer-tag {
  font-size: .78rem;
  color: rgba(255,255,255,.65);
  text-decoration: none;
  padding: .2rem .55rem;
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 20px;
  transition: border-color .15s, color .15s;
}
.footer-tag:hover { color: #fff; border-color: rgba(255,255,255,.4); }
.footer-tag:focus-visible { outline: 2px solid var(--gold); }
.footer-links-group nav { display: flex; flex-direction: column; gap: .35rem; }
.footer-link {
  font-size: .82rem;
  color: rgba(255,255,255,.6);
  text-decoration: none;
  transition: color .15s;
}
.footer-link:hover { color: #fff; }
.footer-link:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding: 1.1rem 1.25rem;
  font-size: .8rem;
  color: rgba(255,255,255,.35);
  text-align: center;
}

/* ── Page title bands (learn, donate, tag) ── */
.page-hero {
  background: var(--navy);
  padding: 2.5rem 0 2rem;
  color: #fff;
}
.page-hero-title {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  font-weight: 800;
  line-height: 1.2;
}
.page-hero-sub {
  color: rgba(255,255,255,.65);
  margin-top: .5rem;
  font-size: .95rem;
}

/* ── Buttons ── */
.btn-primary {
  display: inline-block;
  background: var(--gold);
  color: var(--navy);
  font-weight: 700;
  font-size: .95rem;
  padding: .8rem 2rem;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  text-decoration: none;
  transition: background .2s, transform .15s;
  text-align: center;
}
.btn-primary:hover { background: var(--gold-dk); transform: translateY(-1px); }
.btn-primary:focus-visible { outline: 3px solid var(--navy); outline-offset: 2px; }
.btn-primary:active { transform: translateY(0); }

.btn-outline {
  display: inline-block;
  background: transparent;
  color: var(--navy);
  font-weight: 600;
  font-size: .9rem;
  padding: .7rem 1.5rem;
  border-radius: 8px;
  border: 2px solid var(--navy);
  cursor: pointer;
  text-decoration: none;
  transition: background .2s, color .2s;
}
.btn-outline:hover { background: var(--navy); color: #fff; }
.btn-outline:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }

/* ── Card shared ── */
.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  border: 1px solid var(--border);
  overflow: hidden;
}

/* ── Curriculum item ── */
.curr-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.25rem;
  background: #fff;
  border-radius: 10px;
  border: 1px solid var(--border);
  text-decoration: none;
  color: var(--text);
  transition: box-shadow .2s, border-color .2s;
  font-weight: 500;
}
.curr-item:hover { box-shadow: 0 4px 16px rgba(0,0,0,.08); border-color: var(--gold); }
.curr-item:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.curr-icon {
  width: 40px; height: 40px;
  background: linear-gradient(135deg, var(--navy), #1e3a8a);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.curr-icon svg { color: var(--gold); }

/* ── Stats grid ── */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1.25rem;
  margin-top: 1.5rem;
}
.stat-card {
  background: #fff;
  border-radius: 10px;
  padding: 1.25rem;
  border: 1px solid var(--border);
  text-align: center;
}
.stat-number {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.1;
}
.stat-label { font-size: .8rem; color: var(--muted); margin-top: .35rem; }

/* ── Popular tags row ── */
.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  padding: 1.25rem 0;
}
.pop-tag {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  padding: .35rem .75rem;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 20px;
  font-size: .8rem;
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  transition: border-color .15s, background .15s;
  white-space: nowrap;
}
.pop-tag:hover { border-color: var(--gold); background: #fffbf0; }
.pop-tag:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.pop-tag-count { color: var(--muted); font-weight: 400; }

/* ── FAQ Accordion ── */
.faq-list { display: flex; flex-direction: column; gap: .5rem; }
.faq-item {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}
.faq-btn {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.1rem 1.25rem;
  background: none;
  border: none;
  text-align: left;
  font-size: .95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  gap: .75rem;
  transition: background .15s;
}
