.curr-item:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.curr-icon {
  width: 40px; height: 40px;
  background: linear-gradient(135deg, var(--navy), #1e3a8a);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.curr-icon svg { color: var(--gold); }

