.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  padding: 1.25rem 0;
}
.pop-tag {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  padding: .35rem .75rem;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 20px;
  font-size: .8rem;
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  transition: border-color .15s, background .15s;
  white-space: nowrap;
}
.pop-tag:hover { border-color: var(--gold); background: #fffbf0; }
.pop-tag:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.pop-tag-count { color: var(--muted); font-weight: 400; }

/* ── FAQ Accordion ── */
.faq-list { display: flex; flex-direction: column; gap: .5rem; }
.faq-item {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}
.faq-btn {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.1rem 1.25rem;
  background: none;
  border: none;
  text-align: left;
  font-size: .95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  gap: .75rem;
  transition: background .15s;
}
.faq-btn:hover { background: #f8fafc; }
.faq-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: -2px; }
.faq-chevron {
  flex-shrink: 0;
  transition: transform .25s ease;
  color: var(--muted);
}
.faq-item.open .faq-chevron { transform: rotate(180deg); }
.faq-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height .3s ease, padding .3s ease;
}
.faq-item.open .faq-body { max-height: 400px; }
.faq-body-inner {
  padding: 0 1.25rem 1.1rem;
  font-size: .9rem;
  color: var(--muted);
  line-height: 1.7;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
